import subprocess
import sys
import unittest
from pathlib import Path

from cart import total_cents


class TotalTests(unittest.TestCase):
    def test_quantities(self):
        self.assertEqual(total_cents([{"price_cents":120,"quantity":3}]),360)


class CliTests(unittest.TestCase):
    def assert_cli_output(self, source, expected):
        root = Path(__file__).resolve().parent
        result = subprocess.run(
            [sys.executable, "-B", str(root / "cart.py"), str(root / source)],
            capture_output=True,
            text=True,
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, expected)
        self.assertEqual(result.stderr, "")

    def test_quantities(self):
        self.assert_cli_output("sample.json", "460\n")

    def test_empty_cart(self):
        self.assert_cli_output("empty-cart.json", "0\n")
